INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l60','carnival','funfair','(流动)游乐场;美语 carnival,英式 funfair') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
