INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l60','mom','mum','妈妈;美语 mom,英式 mum') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l60','the moment (一…就)','',NULL,'/ðə ˈmoʊmənt/','The moment you leave, you''ll get a surprise.','你一离开就会大吃一惊。','The moment he arrives, I''ll call you.','他一到我就打给你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l60','be going to','',NULL,'/biː ˈɡoʊɪŋ tuː/','I am going to travel by air.','我打算坐飞机旅行。','It''s going to rain.','要下雨了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l60','rush towards','',NULL,'/rʌʃ təˈwɔːrdz/','A woman rushed towards me.','一个女人向我冲来。','The kids rushed towards the door.','孩子们冲向门口。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l60','come true','',NULL,'/kʌm truː/','Did what she said come true?','她说的应验了吗?','His dream came true.','他的梦想实现了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp1','choice','{"stem":"\"A relation of yours ___ come to see you.\"(表将来''将要'',助动词)","options":["will","did","has","is"],"answer_index":0,"stem_cn":"您的一个亲戚就要来看您了。","explanation_cn":"表示将来\"将要、就要\"用 will + 动词原形。✓ A relation of yours will come to see you. ✗ is:be 动词不单独表将来动作;✗ has:构不成将来;✗ did:过去。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp1','choice','{"stem":"\"You ___ get a big surprise.\"(表将来''会'',助动词)","options":["have","are","did","will"],"answer_index":3,"stem_cn":"您会大吃一惊。","explanation_cn":"表示将来\"会\"用 will + 动词原形。✓ You will get a big surprise. ✗ are:be 动词不单独表将来;✗ have:构不成将来;✗ did:过去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp2','choice','{"stem":"\"I ___ to travel by air.\"(表打算、计划做某事)","options":["will going","go","am going","am go"],"answer_index":2,"stem_cn":"我打算乘飞机旅游。","explanation_cn":"表示打算、计划做某事用 be going to + 原形;主语 I 用 am going to。✓ I am going to travel by air. ✗ will going:will 后接原形不接 going;✗ go:缺将来标志;✗ am go:be going to 固定结构。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp2','choice','{"stem":"\"Look at the clouds! It ___ to rain.\"(根据迹象预测''就要…了'')","options":["will going","is go","goes","is going"],"answer_index":3,"stem_cn":"看那些云!要下雨了。","explanation_cn":"根据迹象预测\"就要…了\"用 be going to;主语 It 用 is going to。✓ It is going to rain. ✗ will going:结构错;✗ goes:一般现在;✗ is go:be going to 固定结构。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp3','choice','{"stem":"\"She ___ this evening and intends to stay for a few days.\"(已安排好的将来,用现在进行时)","options":["is arriving","arrived","will arriving","arrives"],"answer_index":0,"stem_cn":"她今晚到达,打算住几天。","explanation_cn":"已安排好的将来活动用现在进行时表将来;\"今晚到达\"用 is arriving。✓ She is arriving this evening. ✗ arrives:一般现在不表这层\"已安排\";✗ arrived:过去;✗ will arriving:will 后接原形。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp3','choice','{"stem":"\"He ___ at four o''clock.\"(已安排好的将来:四点来)","options":["comes","is coming","will coming","came"],"answer_index":1,"stem_cn":"他四点钟来。","explanation_cn":"已安排好的将来用现在进行时;\"四点来\"用 is coming。✓ He is coming at four o''clock. ✗ comes:一般现在;✗ came:过去;✗ will coming:will 后接原形。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp3','choice','{"stem":"\"She ___ in two days'' time.\"(已安排好的将来:两天后离开)","options":["is leaving","leaves","will leaving","left"],"answer_index":0,"stem_cn":"她两天后动身。","explanation_cn":"已安排好的将来用现在进行时;\"两天后离开\"用 is leaving。✓ She is leaving in two days'' time. ✗ leaves:一般现在;✗ left:过去;✗ will leaving:will 后接原形。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp4','choice','{"stem":"\"The moment you ___ this tent, you will get a big surprise.\"(时间状语从句里用一般现在时表将来)","options":["left","leave","will leave","are leaving"],"answer_index":1,"stem_cn":"您一走出这帐篷,就会大吃一惊。","explanation_cn":"在 the moment 引导的时间状语从句中,用一般现在时表将来(主句用 will)。✓ The moment you leave this tent, you will get a big surprise. ✗ will leave:从句中不用 will 表将来;✗ left:过去;✗ are leaving:此处用一般现在。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp4','choice','{"stem":"\"If it ___ tomorrow, we shall stay at home.\"(条件状语从句里用一般现在时表将来)","options":["rained","will rain","is raining","rains"],"answer_index":3,"stem_cn":"如果明天下雨,我们就待在家里。","explanation_cn":"在 if 引导的条件状语从句中,用一般现在时表将来(主句用 shall/will)。✓ If it rains tomorrow, we shall stay at home. ✗ will rain:条件从句中不用 will;✗ rained:过去;✗ is raining:此处用一般现在。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp4','choice','{"stem":"\"I shall let you know the moment he ___.\"(时间状语从句里用一般现在时表将来)","options":["arrives","is arriving","arrived","will arrive"],"answer_index":0,"stem_cn":"他一到我就通知你。","explanation_cn":"在 the moment 引导的时间状语从句中,用一般现在时表将来。✓ I shall let you know the moment he arrives. ✗ will arrive:从句中不用 will;✗ arrived:过去;✗ is arriving:此处用一般现在。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp4','choice','{"stem":"\"As soon as the rain ___, we shall go out.\"(时间状语从句里用一般现在时表将来)","options":["is stopping","stopped","stops","will stop"],"answer_index":2,"stem_cn":"雨一停我们就出去。","explanation_cn":"在 as soon as 引导的时间状语从句中,用一般现在时表将来。✓ As soon as the rain stops, we shall go out. ✗ will stop:从句中不用 will;✗ stopped:过去;✗ is stopping:此处用一般现在。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp4','choice','{"stem":"\"I''ll give him the message when he ___.\"(时间状语从句里用一般现在时表将来)","options":["will return","returns","returned","is returning"],"answer_index":1,"stem_cn":"他回来时我就把口信给他。","explanation_cn":"在 when 引导的时间状语从句中,用一般现在时表将来。✓ I''ll give him the message when he returns. ✗ will return:从句中不用 will;✗ returned:过去;✗ is returning:此处用一般现在。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp5','choice','{"stem":"\"We went to the fair in the village. = We went to the ___.\"(用名词直接修饰,''乡村的集市''紧凑说法)","options":["fair of village","village''s fair","fair village","village fair"],"answer_index":3,"stem_cn":"我们去了乡村集市。","explanation_cn":"用名词直接修饰名词(复合名词)代替介词短语:the fair in the village = the village fair。✓ We went to the village fair. ✗ fair village:词序颠倒意思变了;✗ village''s fair / fair of village:此处习惯用名词直接修饰。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp5','choice','{"stem":"\"He told us a story about ghosts. = He told us a ___.\"(用名词直接修饰,''关于鬼的故事''紧凑说法)","options":["ghost story","story ghost","ghosts story","story of ghost"],"answer_index":0,"stem_cn":"他给我们讲了个鬼故事。","explanation_cn":"用名词直接修饰名词:a story about ghosts = a ghost story。✓ He told us a ghost story. ✗ story ghost:词序颠倒;✗ ghosts story:定语名词用单数;✗ story of ghost:此处习惯用名词直接修饰。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp5','choice','{"stem":"\"She gave me a present for my birthday. = a ___.\"(用名词直接修饰,''生日的礼物''紧凑说法)","options":["present of birthday","birthday present","birthday''s present","present birthday"],"answer_index":1,"stem_cn":"她送了我一件生日礼物。","explanation_cn":"用名词直接修饰名词:a present for my birthday = a birthday present。✓ a birthday present. ✗ present birthday:词序颠倒;✗ birthday''s present / present of birthday:此处习惯用名词直接修饰。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp5','choice','{"stem":"\"He sent me a card for Christmas. = a ___.\"(用名词直接修饰,''圣诞的贺卡''紧凑说法)","options":["Christmas card","Christmas''s card","card of Christmas","card Christmas"],"answer_index":0,"stem_cn":"他给我寄了张圣诞卡。","explanation_cn":"用名词直接修饰名词:a card for Christmas = a Christmas card。✓ a Christmas card. ✗ card Christmas:词序颠倒;✗ Christmas''s card / card of Christmas:此处习惯用名词直接修饰。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp6','choice','{"stem":"\"She will be arriving this evening and ___ to stay for a few days.\"(打算、意图做某事)","options":["intend","intends","intending","intended"],"answer_index":1,"stem_cn":"她今晚到达,打算住几天。","explanation_cn":"\"打算、意图做某事\"用 intend to do;主语 she 用 intends。✓ She intends to stay for a few days. ✗ intend:主语第三人称单数要加 s;✗ intending:缺谓语;✗ intended:此处讲现在的打算用一般现在。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',5,'am2_l60_gp6','choice','{"stem":"\"A woman will rush ___ you and speak to you.\"(朝某人''冲过来''的方向介词)","options":["against","away","off","towards"],"answer_index":3,"stem_cn":"一个女人会向您冲来跟您说话。","explanation_cn":"\"朝某人冲过来\"用 rush towards,方向介词是 towards。✓ A woman will rush towards you. ✗ against:表\"反对/靠着\";✗ away:表离开;✗ off:表脱离。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',6,NULL,'choice','{"stem":"美语里\"电影\"常说:","options":["film","movie","cinema film","picture show"],"answer_index":1,"explanation_cn":"美语\"电影\"常说 movie;英式说 film。✓ go to the movies 去看电影。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',6,NULL,'choice','{"stem":"美语里\"(流动)游乐场、嘉年华\"常说:","options":["play ground","funfair","carnival","fun park"],"answer_index":2,"explanation_cn":"美语\"(流动)游乐场、嘉年华\"常说 carnival;英式说 funfair。✓ have fun at the carnival 在游乐场玩。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',6,NULL,'choice','{"stem":"future 的意思是:","options":["习惯","过去","现在","未来,前途"],"answer_index":3,"explanation_cn":"future = 未来、前途。✓ The future 卜算未来。\n顺带记:过去 = past;现在 = present;习惯 = habit."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',6,NULL,'choice','{"stem":"relation 的意思是:","options":["亲属,亲戚","朋友","邻居","陌生人"],"answer_index":0,"explanation_cn":"relation = 亲属、亲戚。✓ A relation of yours 您的一位亲戚。\n顺带记:朋友 = friend;邻居 = neighbor;陌生人 = stranger."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',6,NULL,'choice','{"stem":"impatiently 的意思是:","options":["高兴地","小心地","不耐烦地","耐心地"],"answer_index":2,"explanation_cn":"impatiently = 不耐烦地。✓ she asked impatiently 她不耐烦地问。\n顺带记:耐心地 = patiently;高兴地 = happily;小心地 = carefully."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',6,NULL,'choice','{"stem":"rush 的意思是:","options":["等待","冲,奔","散步","停下"],"answer_index":1,"explanation_cn":"rush = 冲、奔。✓ rush towards you 向您冲来。\n顺带记:散步 = stroll;停下 = stop;等待 = wait."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',7,NULL,'cloze','{"stem":"第 1 空","context":"A relation of yours ___1___ this evening. The moment you ___2___ this tent, you ___3___ a big surprise. A woman you know well ___4___ towards you.","blank_no":1,"options":["is arriving","arrived","arrives","was arriving"],"answer_index":0,"explanation_cn":"已安排好的将来用现在进行时表将来。✓ A relation of yours is arriving this evening.\n✗ arrived:过去;✗ arrives:一般现在不表\"已安排\";✗ was arriving:过去进行。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',7,NULL,'cloze','{"stem":"第 2 空","context":"A relation of yours ___1___ this evening. The moment you ___2___ this tent, you ___3___ a big surprise. A woman you know well ___4___ towards you.","blank_no":2,"options":["leave","will leave","left","are leaving"],"answer_index":0,"explanation_cn":"在 the moment 引导的时间状语从句中用一般现在时表将来。✓ The moment you leave this tent…\n✗ will leave:从句中不用 will;✗ left:过去;✗ are leaving:此处用一般现在。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',7,NULL,'cloze','{"stem":"第 3 空","context":"A relation of yours ___1___ this evening. The moment you ___2___ this tent, you ___3___ a big surprise. A woman you know well ___4___ towards you.","blank_no":3,"options":["will get","get","got","are getting"],"answer_index":0,"explanation_cn":"主句表将来用 will + 原形。✓ you will get a big surprise.\n✗ get:缺将来标志;✗ got:过去;✗ are getting:现在进行不表将来结果。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',7,NULL,'cloze','{"stem":"第 4 空","context":"A relation of yours ___1___ this evening. The moment you ___2___ this tent, you ___3___ a big surprise. A woman you know well ___4___ towards you.","blank_no":4,"options":["will rush","rushes","rushed","is rush"],"answer_index":0,"explanation_cn":"表将来用 will + 原形。✓ A woman you know well will rush towards you.\n✗ rushes:一般现在;✗ rushed:过去;✗ is rush:结构错。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',8,NULL,'choice','{"stem":"Who did the writer visit at the village fair?","options":["His sister","A fortune-teller called Madam Bellinsky","A shopkeeper","A doctor"],"answer_index":1,"explanation_cn":"课文说 I decided to visit a fortune-teller called Madam Bellinsky。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',8,NULL,'choice','{"stem":"What did the fortune-teller predict?","options":["He would travel abroad","He would get sick","He would win money","A relation would come, and a woman he knows well would rush towards him"],"answer_index":3,"explanation_cn":"课文说算命人预言 a relation is coming… a woman you know well will rush towards you。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',8,NULL,'choice','{"stem":"Who actually rushed towards him outside the tent?","options":["His wife","A stranger","His sister","The fortune-teller"],"answer_index":0,"explanation_cn":"课文说 my wife hurried towards me,冲向他的其实是他妻子。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',9,NULL,'choice','{"stem":"你想说\"她今晚到达\"(已安排好的将来用现在进行时):","options":["She arrives this evening will.","She is arriving this evening.","She will arriving this evening.","She arrive this evening."],"answer_index":1,"explanation_cn":"已安排好的将来活动用现在进行时表将来。✓ She is arriving this evening. 场合:说已经定好的将来安排。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',9,NULL,'choice','{"stem":"你想说\"如果明天下雨,我们就待在家里\"(条件从句用一般现在表将来):","options":["If it rained tomorrow, we will stay at home.","If it is raining tomorrow, we will stay at home.","If it will rain tomorrow, we will stay at home.","If it rains tomorrow, we will stay at home."],"answer_index":3,"explanation_cn":"在 if 引导的条件句里,\"如果…\"部分用一般现在时表将来(rains),后面主句用 will。✓ If it rains tomorrow, we will stay at home. 场合:说将来某条件下会怎样。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',9,NULL,'choice','{"stem":"你想说\"他给我寄了张圣诞卡\"(用名词作定语 Christmas card):","options":["He sent me a Christmas card.","He sent me a Christmas''s card.","He sent me a card Christmas.","He sent me a card of Christmas."],"answer_index":0,"explanation_cn":"用名词直接修饰名词:a card for Christmas = a Christmas card。✓ He sent me a Christmas card. 场合:把''为…的/关于…的''紧凑成一个名词直接修饰另一个名词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"future 的意思是:","options":["习惯","未来,前途","现在","过去"],"answer_index":1,"explanation_cn":"future = 未来、前途。✓ The future 卜算未来。\n顺带记:过去 = past;现在 = present;习惯 = habit."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"relation 的意思是:","options":["亲属,亲戚","陌生人","朋友","邻居"],"answer_index":0,"explanation_cn":"relation = 亲属、亲戚。✓ A relation of yours 您的一位亲戚。\n顺带记:朋友 = friend;邻居 = neighbor;陌生人 = stranger."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"\"The moment you ___ this tent, you will get a surprise.\"(时间从句用一般现在表将来)","options":["left","will leave","leave","are leaving"],"answer_index":2,"stem_cn":"您一走出这帐篷,就会大吃一惊。","explanation_cn":"在 the moment 引导的时间状语从句中用一般现在时表将来。✓ The moment you leave this tent, you will get a surprise.\n✗ will leave:从句中不用 will;✗ left:过去;✗ are leaving:此处用一般现在。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"\"She ___ this evening and intends to stay.\"(现在进行表已安排的将来)","options":["will arriving","arrived","arrives","is arriving"],"answer_index":3,"stem_cn":"她今晚到达,打算住几天。","explanation_cn":"已安排好的将来用现在进行时表将来。✓ She is arriving this evening and intends to stay.\n✗ arrives:一般现在;✗ arrived:过去;✗ will arriving:will 后接原形。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"\"the moment (you leave)\" 作连词的意思是:","options":["同时","一…就…","很久以前","过一会儿"],"answer_index":1,"explanation_cn":"the moment 作连词 = 一…就…(相当于 as soon as)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"\"come true\" 的意思是:","options":["说真话","变旧","实现,应验","赶来"],"answer_index":2,"explanation_cn":"come true = (预言、梦想)实现、应验。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"What surprise happened as the writer left the tent?","options":["A storm began","He found money","Nothing happened","His wife rushed towards him, matching the prediction"],"answer_index":3,"passage":"At a village fair, I decided to visit a fortune-teller called Madam Bellinsky. I went into her tent and she told me to sit down. After I had given her some money, she looked into a crystal ball and said: ''A relation of yours is coming to see you. She will be arriving this evening and intends to stay for a few days. The moment you leave this tent, you will get a big surprise. A woman you know well will rush towards you. She will speak to you and then she will lead you away from this place. That is all.'' As soon as I went outside, I forgot all about Madam Bellinsky because my wife hurried towards me. ''Where have you been hiding?'' she asked impatiently. ''Your sister will be here in less than an hour and we must be at the station to meet her. We are late already.'' As she walked away, I followed her out of the fair.","explanation_cn":"课文说 my wife hurried towards me,正应了''a woman you know well will rush towards you''的预言。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"How did the fortune-teller''s words match what happened?","options":["Nothing she said happened","He got rich as predicted","A woman he knew well (his wife) rushed towards him and led him away, as predicted","A stranger attacked him"],"answer_index":2,"passage":"At a village fair, I decided to visit a fortune-teller called Madam Bellinsky. I went into her tent and she told me to sit down. After I had given her some money, she looked into a crystal ball and said: ''A relation of yours is coming to see you. She will be arriving this evening and intends to stay for a few days. The moment you leave this tent, you will get a big surprise. A woman you know well will rush towards you. She will speak to you and then she will lead you away from this place. That is all.'' As soon as I went outside, I forgot all about Madam Bellinsky because my wife hurried towards me. ''Where have you been hiding?'' she asked impatiently. ''Your sister will be here in less than an hour and we must be at the station to meet her. We are late already.'' As she walked away, I followed her out of the fair.","explanation_cn":"课文里妻子冲来、说话、带他离开集市,恰好对上算命人说的三步。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"What did the wife say they had to do?","options":["Find the fortune-teller","Go to the station to meet his sister","Buy tickets","Go home right away"],"answer_index":1,"audio":"At a village fair, I decided to visit a fortune-teller called Madam Bellinsky. I went into her tent and she told me to sit down. After I had given her some money, she looked into a crystal ball and said: ''A relation of yours is coming to see you. She will be arriving this evening and intends to stay for a few days. The moment you leave this tent, you will get a big surprise. A woman you know well will rush towards you. She will speak to you and then she will lead you away from this place. That is all.'' As soon as I went outside, I forgot all about Madam Bellinsky because my wife hurried towards me. ''Where have you been hiding?'' she asked impatiently. ''Your sister will be here in less than an hour and we must be at the station to meet her. We are late already.'' As she walked away, I followed her out of the fair.","explanation_cn":"课文说 we must be at the station to meet her(your sister),要去车站接姐姐。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l60',10,NULL,'choice','{"stem":"How did the wife speak to him?","options":["Fearfully","Softly","Cheerfully","Impatiently"],"answer_index":3,"audio":"At a village fair, I decided to visit a fortune-teller called Madam Bellinsky. I went into her tent and she told me to sit down. After I had given her some money, she looked into a crystal ball and said: ''A relation of yours is coming to see you. She will be arriving this evening and intends to stay for a few days. The moment you leave this tent, you will get a big surprise. A woman you know well will rush towards you. She will speak to you and then she will lead you away from this place. That is all.'' As soon as I went outside, I forgot all about Madam Bellinsky because my wife hurried towards me. ''Where have you been hiding?'' she asked impatiently. ''Your sister will be here in less than an hour and we must be at the station to meet her. We are late already.'' As she walked away, I followed her out of the fair.","explanation_cn":"课文说 ''Where have you been hiding?'' she asked impatiently,妻子不耐烦地问。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l61',2,8,61,'Trouble with the Hubble','哈勃望远镜的困境','KS37 表示将来的三种时态(将来进行时 will be doing、将来完成时 will have done、将来完成进行时 will have been doing)(教材 L61 Key structures)主考;时间/条件状语从句用一般现在/现在完成表将来(by the time you read this、the moment he has arrived)+ SD cost/price/value 名词与动词辨析(辅考)','哈勃望远镜于1990年4月20日由国家航空航天局发射升空,耗资10多亿美元。从最开始哈勃望远镜就有问题:它传送给我们的图像很令人失望,因为它的主镜子有误差。国家航空航天局准备纠正这一错误,为此不久将把4名宇航员送入太空修复望远镜。“奋进”号航天飞机将把宇航员送上哈勃。“奋进”号上的一只机器手将抓住望远镜并托住它,同时宇航员进行必要的修复工作。当然,哈勃位于地球大气层之外,因此它很快就会给我们传送来我们所见到过的、有关行星和遥远星系的最清晰的照片。哈勃将告诉我们许多有关宇宙的年龄和大小的事情。等到你读到这篇文章时,敏锐的哈勃望远镜已经为我们送来了成千上万张精彩的照片。','{"q":"Listen and answer — What is the special importance of a telescope in space?","options":["Being above the atmosphere, it sends the clearest pictures of stars and distant galaxies","It is cheaper to build than one on earth","It can be repaired only by astronauts","It can travel to other galaxies"],"answer_index":0}'::jsonb,'{"title":"表示将来的三种时态","intro":"KS37 三种将来时态:①将来进行时 will be + 现在分词——表示将来某时正在进行的动作(I will be writing letters all day tomorrow);②将来完成时 will have + 过去分词——表示到将来某时已经完成的动作(Soon the astronauts will have repaired it);③将来完成进行时 will have been + 现在分词——表示到将来某时为止一直持续的动作(By Friday they will have been working on it for seven days)。","table":{"headers":["时态","结构","例子"],"rows":[["将来进行时","will be + doing","I will be writing letters all day tomorrow."],["将来完成时","will have + done","Soon the astronauts will have repaired the telescope."],["将来完成进行时","will have been + doing","By Friday, they will have been working on it for seven days."],["将来完成时(时间点)","will have + done + by...","He will have arrived by this time tomorrow."]]},"specialRules":[{"rule":"在 by the time/the moment/as soon as 等引导的时间、条件状语从句中,用一般现在时或现在完成时表示将来,主句用将来时:By the time you read this, the Hubble will have sent us pictures;The moment he has arrived, I will let you know。","mark":"从句表将来"},{"rule":"SD 易混词 cost/price/value:①作名词——cost 成本/造价(at a cost of),price 价钱(ask the price),value 价值(sentimental value);②作动词——cost 花费多少钱(What does it cost?),price 给…定价/问价(price the goods),value 重视/珍视(I value your advice)。","mark":"cost/price/value"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l61',1,NULL,'The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars. Right from the start there was trouble with the Hubble.','哈勃望远镜于1990年4月20日由国家航空航天局发射升空,耗资10多亿美元。从最开始哈勃望远镜就有问题。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l61',2,NULL,'The pictures it sent us were very disappointing because its main mirror was faulty! NASA is now going to put the telescope right, so it will soon be sending up four astronauts to repair it.','它传送给我们的图像很令人失望,因为它的主镜子有误差!国家航空航天局准备纠正这一错误,为此不久将把4名宇航员送入太空修复它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l61',3,NULL,'The shuttle Endeavour will be taking the astronauts to the Hubble. A robot-arm from the Endeavour will grab the telescope and hold it while the astronauts make the necessary repairs.','“奋进”号航天飞机将把宇航员送上哈勃。“奋进”号上的一只机器手将抓住望远镜并托住它,同时宇航员进行必要的修复工作。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l61',4,NULL,'Of course, the Hubble is above the earth''s atmosphere, so it will soon be sending us the clearest pictures of the stars and distant galaxies that we have ever seen.','当然,哈勃位于地球大气层之外,因此它很快就会给我们传送来我们所见到过的、有关行星和遥远星系的最清晰的照片。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l61',5,NULL,'The Hubble will tell us a great deal about the age and size of the universe. By the time you read this, the Hubble''s eagle eye will have sent us thousands and thousands of wonderful pictures.','哈勃将告诉我们许多有关宇宙的年龄和大小的事情。等到你读到这篇文章时,敏锐的哈勃望远镜已经为我们送来了成千上万张精彩的照片。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l61','Hubble','/ˈhʌbl/','n','哈勃(望远镜名)','the Hubble telescope') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l61','telescope','/ˈtelɪskoʊp/','n','望远镜','The Hubble telescope was launched into space.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
