INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l61','right from the start','',NULL,'/raɪt frəm ðə stɑːrt/','Right from the start there was trouble with the Hubble.','从一开始哈勃就有问题。','I knew right from the start it would work.','我从一开始就知道它会成功。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l61','at a cost of','',NULL,'/æt ə kɔːst əv/','It was launched at a cost of over a billion dollars.','它的发射耗资10多亿美元。','The bridge was built at a cost of $50 million.','这座桥造价5000万美元。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l61','a great deal','',NULL,'/ə ɡreɪt diːl/','The Hubble will tell us a great deal about the universe.','哈勃将告诉我们许多有关宇宙的事。','I learned a great deal from her.','我从她那里学到了很多。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l61','put ... right','',NULL,'/pʊt raɪt/','NASA is going to put the telescope right.','国家航空航天局准备把望远镜纠正好。','Don''t worry, we''ll put it right.','别担心,我们会把它修好。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp1','choice','{"stem":"\"NASA will soon ___ up four astronauts to repair the telescope.\"(将来进行时:不久将在派…)","options":["sending","be sending","send","have sent"],"answer_index":1,"stem_cn":"国家航空航天局不久将派4名宇航员去修理它。","explanation_cn":"将来进行时 = will be + 现在分词,表示将来某段时间正在进行的动作;will soon be sending 意为\"不久将在派\"。✓ NASA will soon be sending up four astronauts. ✗ send:will send 只是一般将来,不强调\"正在进行\";✗ have sent:将来完成;✗ sending:缺 will be。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp1','choice','{"stem":"\"The shuttle Endeavour ___ the astronauts to the Hubble.\"(将来进行时)","options":["is taking","will take","will be taking","will have taken"],"answer_index":2,"stem_cn":"“奋进”号航天飞机将把宇航员送上哈勃。","explanation_cn":"将来进行时 will be + 现在分词。✓ The shuttle Endeavour will be taking the astronauts to the Hubble. ✗ will take:一般将来,不强调过程正在进行;✗ will have taken:将来完成;✗ is taking:现在进行。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp1','choice','{"stem":"\"It will soon ___ us the clearest pictures of the stars.\"(将来进行时)","options":["sent","have sent","send","be sending"],"answer_index":3,"stem_cn":"它很快就会给我们传来最清晰的星星照片。","explanation_cn":"将来进行时 will be + 现在分词;will soon be sending 表示不久将持续传送。✓ It will soon be sending us the clearest pictures. ✗ send:一般将来;✗ sent:过去;✗ have sent:将来完成缺 be…ing。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp1','choice','{"stem":"\"I ___ letters all day tomorrow.\"(将来进行时:明天一整天都在做)","options":["will have written","will be writing","will write","am writing"],"answer_index":1,"stem_cn":"明天我一整天都会在写信。","explanation_cn":"将来进行时表示将来某段时间一直在做;\"明天一整天都在写信\"用 will be writing。✓ I will be writing letters all day tomorrow. ✗ will write:一般将来,不强调\"一整天持续\";✗ will have written:将来完成;✗ am writing:现在进行。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp2','choice','{"stem":"\"Soon the astronauts ___ the telescope.\"(将来完成时:很快就把…修好了)","options":["will have repaired","will be repairing","have repaired","will repair"],"answer_index":0,"stem_cn":"宇航员很快就会把望远镜修好。","explanation_cn":"将来完成时 = will have + 过去分词,表示到将来某时已经完成。✓ Soon the astronauts will have repaired the telescope. ✗ will repair:一般将来,不表\"已完成\";✗ will be repairing:将来进行;✗ have repaired:现在完成。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp2','choice','{"stem":"\"By the time you read this, the Hubble''s eagle eye ___ us thousands of pictures.\"(将来完成时:到那时已经…)","options":["has sent","will be sending","will have sent","will send"],"answer_index":2,"stem_cn":"等你读到这里时,哈勃已经给我们送来数千张照片了。","explanation_cn":"\"By the time you read this\"指到将来某时,主句用将来完成时表\"到那时已经完成\"。✓ the Hubble''s eagle eye will have sent us thousands of pictures. ✗ will send:一般将来;✗ will be sending:将来进行;✗ has sent:现在完成。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp2','choice','{"stem":"\"He ___ by this time tomorrow.\"(将来完成时:到明天这时候已经…)","options":["will be arriving","will arrive","has arrived","will have arrived"],"answer_index":3,"stem_cn":"明天这个时候他已经到了。","explanation_cn":"\"by this time tomorrow\"是将来的时间点,用将来完成时表\"到那时已经到达\"。✓ He will have arrived by this time tomorrow. ✗ will arrive:一般将来,不表\"到那时已完成\";✗ will be arriving:将来进行;✗ has arrived:现在完成。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp2','choice','{"stem":"\"He will phone us later; he ___ his exam results by then.\"(将来完成时:到那时已经收到)","options":["will have received","will be receiving","will receive","has received"],"answer_index":0,"stem_cn":"他晚点会给我们打电话,那时他已经收到考试成绩了。","explanation_cn":"\"by then\"指将来某时之前,用将来完成时表\"到那时已经收到\"。✓ He will have received his exam results by then. ✗ will receive:一般将来;✗ will be receiving:将来进行;✗ has received:现在完成。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp3','choice','{"stem":"\"By Friday midday, they ___ on it for seven days.\"(将来完成进行时:到周五中午已持续做了7天)","options":["will be working","will have been working","will work","will have worked"],"answer_index":1,"stem_cn":"到星期五中午,他们就在这个工程上干了7天了。","explanation_cn":"将来完成进行时 = will have been + 现在分词,表示到将来某时为止一直持续的动作,常与\"for + 时间段\"连用。✓ By Friday midday, they will have been working on it for seven days. ✗ will work:一般将来;✗ will have worked:将来完成,不强调\"一直持续到那时\";✗ will be working:将来进行。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp3','choice','{"stem":"\"By the end of this year, I ___ English for five years.\"(将来完成进行时:到今年年底已经学了5年)","options":["will have learned","will learn","will have been learning","will be learning"],"answer_index":2,"stem_cn":"到今年年底,我学英语就满5年了。","explanation_cn":"将来完成进行时,强调到将来某时为止已持续多久;\"到年底学了5年\"用 will have been learning。✓ By the end of this year, I will have been learning English for five years. ✗ will learn:一般将来;✗ will have learned:将来完成,不强调持续过程;✗ will be learning:将来进行。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp4','choice','{"stem":"\"By the time you ___ this, the Hubble will have sent us many pictures.\"(时间状语从句用一般现在时表将来)","options":["will read","will have read","are reading","read"],"answer_index":3,"stem_cn":"等你读到这篇文章时……","explanation_cn":"在 by the time 引导的时间状语从句中,用一般现在时表将来(主句用将来时)。✓ By the time you read this, the Hubble will have sent us many pictures. ✗ will read:从句中不用 will 表将来;✗ will have read:同理;✗ are reading:此处用一般现在。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp4','choice','{"stem":"\"The moment he ___, I will let you know.\"(时间状语从句用现在完成时表''一…就…'')","options":["is arriving","will arrive","has arrived","will have arrived"],"answer_index":2,"stem_cn":"他一到我就通知你。","explanation_cn":"在 the moment 引导的从句中,可用现在完成时表\"一…(完成)就…\";主句用将来时。✓ The moment he has arrived, I will let you know. ✗ will arrive:从句中不用 will;✗ will have arrived:从句中不用将来完成;✗ is arriving:此处用现在完成表\"到达完成\"。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp4','choice','{"stem":"\"As soon as he ___ his exam results, he will phone us.\"(时间状语从句用现在完成时表''一…就…'')","options":["is receiving","has received","will receive","will have received"],"answer_index":1,"stem_cn":"他一收到考试成绩就会给我们打电话。","explanation_cn":"在 as soon as 引导的从句中,用现在完成时表\"一…(收到)就…\";主句用将来时。✓ As soon as he has received his exam results, he will phone us. ✗ will receive:从句中不用 will;✗ will have received:从句中不用将来完成;✗ is receiving:此处用现在完成。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp5','choice','{"stem":"\"There has been a sharp rise in the ___ of living.\"(名词:''生活费用/成本'')","options":["expense","price","cost","value"],"answer_index":2,"stem_cn":"生活费用急剧上涨。","explanation_cn":"\"生活费用、生活成本\"是 the cost of living,cost 作名词表\"成本、费用\"。✓ a sharp rise in the cost of living. ✗ price:指某物标出的售价,不用于\"生活费用\"这个固定说法;✗ value:指价值;✗ expense:虽近义但固定短语是 cost of living。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp5','choice','{"stem":"\"How much is that blouse? Let''s ask the ___.\"(名词:问''价钱'')","options":["money","cost","value","price"],"answer_index":3,"stem_cn":"那件衬衫多少钱?我们问问价钱。","explanation_cn":"询问某商品\"卖多少钱\"用名词 price(价钱)。✓ How much is that blouse? Let''s ask the price. ✗ cost:侧重成本/造价,问店里售价习惯用 price;✗ value:价值;✗ money:泛指钱,不表\"价钱\"。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp5','choice','{"stem":"\"The stolen items were of sentimental ___, rather than financial.\"(名词:情感''价值'')","options":["number","cost","value","price"],"answer_index":2,"stem_cn":"被盗物品更具有情感上的价值,而非经济上的。","explanation_cn":"\"情感上的价值\"用名词 value(价值)。✓ The stolen items were of sentimental value. ✗ price:标价;✗ cost:成本;✗ number:数量,不表价值。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp6','choice','{"stem":"\"What does this blouse ___, please?\"(动词:询问''多少钱'')","options":["cost","pay","value","price"],"answer_index":0,"stem_cn":"请问,这件衬衫多少钱?","explanation_cn":"询问某物\"要花多少钱\"用动词 cost。✓ What does this blouse cost, please? ✗ price:作动词是\"给…定价/问价\",不用来直接问\"多少钱\";✗ value:作动词是\"重视\";✗ pay:付钱的对象是人,不这样搭配问价。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',5,'am2_l61_gp6','choice','{"stem":"\"I ___ your advice a great deal.\"(动词:非常''看重、珍视'')","options":["price","cost","spend","value"],"answer_index":3,"stem_cn":"我非常尊重你的建议。","explanation_cn":"\"非常看重、珍视\"某物用动词 value。✓ I value your advice a great deal. ✗ cost:花费;✗ price:定价;✗ spend:花(钱/时间),搭配不同。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',6,NULL,'choice','{"stem":"美语里\"钞票、纸币\"常说:","options":["cash note","note","bill","paper money"],"answer_index":2,"explanation_cn":"美语\"钞票、纸币\"常说 bill(如 a ten-dollar bill);英式说 note。✓ a ten-dollar bill 一张十美元的钞票。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',6,NULL,'choice','{"stem":"美语里\"(餐馆结账的)账单\"常说:","options":["note","list","bill","check"],"answer_index":3,"explanation_cn":"美语\"(餐馆结账的)账单\"常说 check;英式说 bill。✓ Can I have the check, please? 请结账。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',6,NULL,'choice','{"stem":"telescope 的意思是:","options":["望远镜","温度计","万花筒","显微镜"],"answer_index":0,"explanation_cn":"telescope = 望远镜。✓ The Hubble telescope 哈勃望远镜。\n顺带记:显微镜 = microscope;温度计 = thermometer;万花筒 = kaleidoscope."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',6,NULL,'choice','{"stem":"launch 的意思是:","options":["降落","修理","发射,发动","停止"],"answer_index":2,"explanation_cn":"launch = 发射、发动。✓ launched into space 发射升空。\n顺带记:降落 = land;停止 = stop;修理 = repair."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',6,NULL,'choice','{"stem":"faulty 的意思是:","options":["遥远的","巨大的","完美的","有错误的,有缺陷的"],"answer_index":3,"explanation_cn":"faulty = 有错误的、有缺陷的。✓ its main mirror was faulty 它的主镜子有误差。\n顺带记:完美的 = perfect;巨大的 = huge;遥远的 = distant."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',6,NULL,'choice','{"stem":"galaxy 的意思是:","options":["月亮","飞船","星系","星星"],"answer_index":2,"explanation_cn":"galaxy = 星系。✓ stars and distant galaxies 行星和遥远的星系。\n顺带记:星星 = star;月亮 = moon;飞船 = spacecraft."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',7,NULL,'cloze','{"stem":"第 1 空","context":"NASA will soon ___1___ up four astronauts to repair the Hubble. The shuttle Endeavour ___2___ the astronauts to it. Soon the astronauts ___3___ the telescope. By the time you read this, the Hubble''s eagle eye ___4___ us thousands of pictures.","blank_no":1,"options":["be sending","send","sent","have sent"],"answer_index":0,"explanation_cn":"将来进行时 will be + 现在分词,表示不久将持续进行。✓ NASA will soon be sending up four astronauts.\n✗ send:一般将来;✗ sent:过去;✗ have sent:将来完成缺 be。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',7,NULL,'cloze','{"stem":"第 2 空","context":"NASA will soon ___1___ up four astronauts to repair the Hubble. The shuttle Endeavour ___2___ the astronauts to it. Soon the astronauts ___3___ the telescope. By the time you read this, the Hubble''s eagle eye ___4___ us thousands of pictures.","blank_no":2,"options":["will be taking","will take","took","is taken"],"answer_index":0,"explanation_cn":"将来进行时。✓ The shuttle Endeavour will be taking the astronauts to it.\n✗ will take:一般将来;✗ took:过去;✗ is taken:现在被动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',7,NULL,'cloze','{"stem":"第 3 空","context":"NASA will soon ___1___ up four astronauts to repair the Hubble. The shuttle Endeavour ___2___ the astronauts to it. Soon the astronauts ___3___ the telescope. By the time you read this, the Hubble''s eagle eye ___4___ us thousands of pictures.","blank_no":3,"options":["will have repaired","repaired","are repairing","repair"],"answer_index":0,"explanation_cn":"将来完成时,表示到将来某时已经修好。✓ Soon the astronauts will have repaired the telescope.\n✗ repaired:过去;✗ are repairing:现在进行;✗ repair:原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',7,NULL,'cloze','{"stem":"第 4 空","context":"NASA will soon ___1___ up four astronauts to repair the Hubble. The shuttle Endeavour ___2___ the astronauts to it. Soon the astronauts ___3___ the telescope. By the time you read this, the Hubble''s eagle eye ___4___ us thousands of pictures.","blank_no":4,"options":["will have sent","will send","is sending","sent"],"answer_index":0,"explanation_cn":"将来完成时,与\"by the time you read this\"呼应。✓ the Hubble''s eagle eye will have sent us thousands of pictures.\n✗ will send:一般将来;✗ is sending:现在进行;✗ sent:过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',8,NULL,'choice','{"stem":"When and by whom was the Hubble telescope launched?","options":["By four astronauts last week","Into space by NASA on April 20, 1990, at a cost of over a billion dollars","By a robot-arm from the earth","By the shuttle Endeavour in 2000"],"answer_index":1,"explanation_cn":"课文说 The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',8,NULL,'choice','{"stem":"Why were the Hubble''s pictures very disappointing at first?","options":["Its main mirror was faulty","It had no power","The astronauts damaged it","It was too far from the stars"],"answer_index":0,"explanation_cn":"课文说 The pictures were very disappointing because its main mirror was faulty。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',8,NULL,'choice','{"stem":"How will the astronauts reach the Hubble to repair it?","options":["They will use another telescope","They will fly there alone in a rocket","The shuttle Endeavour will take them, and a robot-arm will hold the telescope","They will not go; it repairs itself"],"answer_index":2,"explanation_cn":"课文说 The shuttle Endeavour will be taking the astronauts to the Hubble, and a robot-arm will grab the telescope and hold it。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',9,NULL,'choice','{"stem":"你想说\"到你读到这封信时,我已经给你寄了照片\"(将来完成时:到将来某时已完成):","options":["By the time you read this, I send you the photos.","By the time you read this, I will have sent you the photos.","By the time you will read this, I will send you the photos.","By the time you read this, I sending you the photos."],"answer_index":1,"explanation_cn":"到将来某时已经完成用将来完成时;从句 you read this 用一般现在表将来,主句 will have sent。✓ By the time you read this, I will have sent you the photos. 场合:说到对方看到时事情早已办好。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',9,NULL,'choice','{"stem":"你想说\"明天这个时候我将正在开会\"(将来进行时:将来某刻正在进行):","options":["This time tomorrow I am will have a meeting.","This time tomorrow I have a meeting.","This time tomorrow I will had a meeting.","This time tomorrow I will be having a meeting."],"answer_index":3,"explanation_cn":"将来某个时刻正在进行的动作用将来进行时 will be + 现在分词。✓ This time tomorrow I will be having a meeting. 场合:说将来某一刻自己正忙着做某事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',9,NULL,'choice','{"stem":"你想问\"这件衬衫多少钱?\"(用动词 cost 表''花费多少钱''):","options":["How much does this blouse value?","What is this blouse costing money?","What does this blouse cost?","What does this blouse price?"],"answer_index":2,"explanation_cn":"询问某物\"要花多少钱\"用动词 cost。✓ What does this blouse cost? 场合:在店里问价。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"telescope 的意思是:","options":["望远镜","温度计","万花筒","显微镜"],"answer_index":0,"explanation_cn":"telescope = 望远镜。✓ The Hubble telescope 哈勃望远镜。\n顺带记:显微镜 = microscope;温度计 = thermometer;万花筒 = kaleidoscope."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"universe 的意思是:","options":["制服","大学","联盟","宇宙"],"answer_index":3,"explanation_cn":"universe = 宇宙。✓ the age and size of the universe 宇宙的年龄和大小。\n顺带记:大学 = university;联盟 = union;制服 = uniform."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"\"By the time you read this, the Hubble ___ us thousands of pictures.\"(将来完成时)","options":["is sending","will have sent","sent","will send"],"answer_index":1,"stem_cn":"等你读到这里时,哈勃已经给我们送来数千张照片了。","explanation_cn":"将来完成时,表示到将来某时已经完成。✓ By the time you read this, the Hubble will have sent us thousands of pictures.\n✗ will send:一般将来;✗ is sending:现在进行;✗ sent:过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"\"This time tomorrow the shuttle ___ the astronauts to the Hubble.\"(将来进行时)","options":["will take","is taken","will be taking","took"],"answer_index":2,"stem_cn":"明天这个时候航天飞机正把宇航员送往哈勃。","explanation_cn":"将来进行时,表示将来某刻正在进行。✓ This time tomorrow the shuttle will be taking the astronauts to the Hubble.\n✗ will take:一般将来;✗ took:过去;✗ is taken:现在被动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"\"will have + 过去分词\"这种形式表示的时间概念是:","options":["将来正在进行","过去已经完成","现在正在进行","到将来某时已经完成"],"answer_index":3,"explanation_cn":"will have + 过去分词是将来完成时,表示到将来某个时间点为止动作已经完成。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"\"at a cost of\" 的意思是:","options":["造价为,耗资","打折出售","免费","用现金支付"],"answer_index":0,"explanation_cn":"at a cost of = 造价为、耗资。✓ launched at a cost of over a billion dollars 发射耗资10多亿美元。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"What was wrong with the Hubble right from the start?","options":["It was launched too late","Its main mirror was faulty, so its pictures were disappointing","It ran out of fuel","Its robot-arm broke"],"answer_index":1,"passage":"The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars. Right from the start there was trouble with the Hubble. The pictures it sent us were very disappointing because its main mirror was faulty! NASA is now going to put the telescope right, so it will soon be sending up four astronauts to repair it. The shuttle Endeavour will be taking the astronauts to the Hubble. A robot-arm from the Endeavour will grab the telescope and hold it while the astronauts make the necessary repairs. Of course, the Hubble is above the earth''s atmosphere, so it will soon be sending us the clearest pictures of the stars and distant galaxies that we have ever seen. The Hubble will tell us a great deal about the age and size of the universe. By the time you read this, the Hubble''s eagle eye will have sent us thousands and thousands of wonderful pictures.","explanation_cn":"课文说 The pictures it sent us were very disappointing because its main mirror was faulty。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"What will the astronauts from the Endeavour do?","options":["Build a new telescope in space","Take photos of one another","Bring the Hubble back to earth","Repair the telescope while a robot-arm grabs and holds it"],"answer_index":3,"passage":"The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars. Right from the start there was trouble with the Hubble. The pictures it sent us were very disappointing because its main mirror was faulty! NASA is now going to put the telescope right, so it will soon be sending up four astronauts to repair it. The shuttle Endeavour will be taking the astronauts to the Hubble. A robot-arm from the Endeavour will grab the telescope and hold it while the astronauts make the necessary repairs. Of course, the Hubble is above the earth''s atmosphere, so it will soon be sending us the clearest pictures of the stars and distant galaxies that we have ever seen. The Hubble will tell us a great deal about the age and size of the universe. By the time you read this, the Hubble''s eagle eye will have sent us thousands and thousands of wonderful pictures.","explanation_cn":"课文说 A robot-arm will grab the telescope and hold it while the astronauts make the necessary repairs。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"How much did the Hubble telescope cost to launch?","options":["Over a billion dollars","Nothing at all","A few thousand dollars","Exactly one million dollars"],"answer_index":0,"audio":"The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars. Right from the start there was trouble with the Hubble. The pictures it sent us were very disappointing because its main mirror was faulty! NASA is now going to put the telescope right, so it will soon be sending up four astronauts to repair it. The shuttle Endeavour will be taking the astronauts to the Hubble. A robot-arm from the Endeavour will grab the telescope and hold it while the astronauts make the necessary repairs. Of course, the Hubble is above the earth''s atmosphere, so it will soon be sending us the clearest pictures of the stars and distant galaxies that we have ever seen. The Hubble will tell us a great deal about the age and size of the universe. By the time you read this, the Hubble''s eagle eye will have sent us thousands and thousands of wonderful pictures.","explanation_cn":"课文说 launched into space by NASA at a cost of over a billion dollars。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l61',10,NULL,'choice','{"stem":"Where is the Hubble in relation to the earth''s atmosphere?","options":["Inside it","Above it, so it sends the clearest pictures","Below it","On the moon"],"answer_index":1,"audio":"The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars. Right from the start there was trouble with the Hubble. The pictures it sent us were very disappointing because its main mirror was faulty! NASA is now going to put the telescope right, so it will soon be sending up four astronauts to repair it. The shuttle Endeavour will be taking the astronauts to the Hubble. A robot-arm from the Endeavour will grab the telescope and hold it while the astronauts make the necessary repairs. Of course, the Hubble is above the earth''s atmosphere, so it will soon be sending us the clearest pictures of the stars and distant galaxies that we have ever seen. The Hubble will tell us a great deal about the age and size of the universe. By the time you read this, the Hubble''s eagle eye will have sent us thousands and thousands of wonderful pictures.","explanation_cn":"课文说 the Hubble is above the earth''s atmosphere, so it will soon be sending us the clearest pictures。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l62',2,8,62,'After the fire','大火之后','KS38 过去完成时(had done)与过去完成进行时(had been doing)的区别(教材 L62 Key structures)主考;宾语从句中主句过去→从句用过去完成 + SD 易混词 control/check、great/big、soil/ground(辅考)','消防队员们同那场森林大火搏斗了将近3个星期才最后把火势控制住。就在不久之前,参天大树还覆盖着方圆数英里的土地。而现在,发热的地面上仍然升腾着烟雾,弥漫在荒凉的山丘上。冬季即将来临,这些山丘对周围的村庄具有毁灭性的威胁,因为大雨不仅会冲走土壤,而且还会引起严重的水灾。在大火最后被扑灭后,森林管理当局订购了好几吨一种生长迅速的特殊类型的草籽。飞机把这种草籽大量地撒播在地上。飞机撒播近一个月后,开始下起雨来。然而到那时,很多地方的草已经生了根。一片片的绿草开始出现在这片烧焦的土地上,代替了那多少世纪以来一直生长在那里的参天大树。','{"q":"Listen and answer — What was the danger to the villages after the fire?","options":["Heavy rain would wash away the soil and cause serious floods","The fire would start again","Wild animals would attack them","The smoke would poison the air"],"answer_index":0}'::jsonb,'{"title":"过去完成时 vs 过去完成进行时","intro":"KS38 两种时态都表示“过去的过去”,区别在于:①过去完成时 had + 过去分词——表示到过去某时已经完成的动作,常与 before/already/by then 连用(He had already finished work before I arrived);②过去完成进行时 had been + 现在分词——强调到过去某时为止一直持续的过程,常与 for + 时段连用(He had been working in a factory for years before he got this job)。","table":{"headers":["时态","结构","例子"],"rows":[["过去完成时","had + done","He had already finished work before I arrived."],["过去完成进行时","had been + doing","He had been working here for years before he got this job."],["宾语从句(完成)","…what he had done","I asked him what he had lost."],["宾语从句(进行)","…what he had been doing","I asked him what he had been doing all afternoon."]]},"specialRules":[{"rule":"在 before/after/when 等连接的两个过去动作中,先发生的用过去完成时,后发生的用一般过去时:When the fire had been put out, the authorities ordered grass-seed。","mark":"过去的过去"},{"rule":"SD 易混词:control=掌管/控制(controls a company) vs check=检查/查验(checked my car engine);great=伟大/重要的(a great composer) vs big=(体积)大的(big buildings);soil=土壤(grow in poor soil) vs ground=地面(fell to the ground)。","mark":"control/check·great/big·soil/ground"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l62',1,NULL,'Firefighters had been fighting the forest fire for nearly three weeks before they could get it under control. A short time before, great trees had covered the countryside for miles around.','消防队员们同那场森林大火搏斗了将近3个星期才最后把火势控制住。就在不久之前,参天大树还覆盖着方圆数英里的土地。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l62',2,NULL,'Now, smoke still rose up from the warm ground over the desolate hills. Winter was coming on and the hills threatened the surrounding villages with destruction,','而现在,发热的地面上仍然升腾着烟雾,弥漫在荒凉的山丘上。冬季即将来临,这些山丘对周围的村庄具有毁灭性的威胁,') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l62',3,NULL,'for heavy rain would not only wash away the soil but would cause serious floods as well. When the fire had at last been put out, the forest authorities ordered several tons of a special type of grass-seed which would grow quickly.','因为大雨不仅会冲走土壤,而且还会引起严重的水灾。在大火最后被扑灭后,森林管理当局订购了好几吨一种生长迅速的特殊类型的草籽。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l62',4,NULL,'The seed was sprayed over the ground in huge quantities by airplanes. The planes had been planting seed for nearly a month when it began to rain.','飞机把这种草籽大量地撒播在地上。飞机撒播近一个月后,开始下起雨来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l62',5,NULL,'By then, however, in many places the grass had already taken root. In place of the great trees which had been growing there for centuries, patches of green had begun to appear in the blackened soil.','然而到那时,很多地方的草已经生了根。一片片的绿草开始出现在这片烧焦的土地上,代替了那多少世纪以来一直生长在那里的参天大树。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
