INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp1','choice','{"stem":"\"A short time before, great trees ___ the countryside for miles around.\"(过去完成时:过去的过去)","options":["had covered","covered","were covering","have covered"],"answer_index":0,"stem_cn":"就在不久之前,参天大树还覆盖着方圆数英里的土地。","explanation_cn":"\"就在不久之前\"指过去某时之前已经完成的状态,用过去完成时 had + 过去分词。✓ A short time before, great trees had covered the countryside. ✗ covered:一般过去,分不出先后;✗ have covered:现在完成;✗ were covering:过去进行。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp1','choice','{"stem":"\"He ___ already finished work before I arrived.\"(过去完成时,before + 一般过去)","options":["was","had","did","has"],"answer_index":1,"stem_cn":"我到达之前他已经完成了工作。","explanation_cn":"过去完成时 = had + 过去分词;\"在我到达之前已经完成\"用 had finished。✓ He had already finished work before I arrived. ✗ has:现在完成,与 before I arrived 的过去时间冲突;✗ was:构不成完成;✗ did:一般过去分不出先后。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp1','choice','{"stem":"\"By then, in many places the grass ___ already taken root.\"(过去完成时,by then)","options":["had","would","was","has"],"answer_index":0,"stem_cn":"到那时,很多地方的草已经生了根。","explanation_cn":"\"by then(到那时)\"指过去某时之前已经完成,用过去完成时 had taken。✓ By then, the grass had already taken root. ✗ has:现在完成;✗ was:构不成完成;✗ would:表将来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp1','choice','{"stem":"\"He ___ in Scotland for fifteen years before he came to England.\"(过去完成时,before + 过去)","options":["lived","had lived","has lived","was living"],"answer_index":1,"stem_cn":"他来英格兰之前在苏格兰住了15年。","explanation_cn":"\"在他来英格兰之前(过去某时)已经住了15年\",用过去完成时。✓ He had lived in Scotland for fifteen years before he came to England. ✗ lived:一般过去分不出先后;✗ has lived:现在完成,与 before he came 的过去冲突;✗ was living:过去进行。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp2','choice','{"stem":"\"Firefighters ___ the forest fire for nearly three weeks before they could get it under control.\"(过去完成进行时:强调持续过程)","options":["had been fighting","were fighting","have been fighting","fought"],"answer_index":0,"stem_cn":"消防员同大火搏斗了将近3个星期才控制住。","explanation_cn":"过去完成进行时 = had been + 现在分词,强调到过去某时为止一直持续的过程,常与 for + 时段连用。✓ Firefighters had been fighting the fire for nearly three weeks. ✗ fought:一般过去,不强调\"一直持续\";✗ have been fighting:现在完成进行;✗ were fighting:过去进行,不含\"持续了三周直到那时\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp2','choice','{"stem":"\"The planes ___ seed for nearly a month when it began to rain.\"(过去完成进行时)","options":["have been planting","were planting","had been planting","planted"],"answer_index":2,"stem_cn":"飞机撒播了近一个月草籽,这时开始下起雨来。","explanation_cn":"过去完成进行时,表示到\"开始下雨\"这一过去时刻为止已持续撒播近一个月。✓ The planes had been planting seed for nearly a month when it began to rain. ✗ planted:一般过去;✗ have been planting:现在完成进行;✗ were planting:过去进行,不含\"持续到那时\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp2','choice','{"stem":"\"In place of the great trees which ___ there for centuries, patches of green appeared.\"(过去完成进行时,for centuries)","options":["were growing","had been growing","have been growing","grew"],"answer_index":1,"stem_cn":"代替了那多少世纪以来一直生长在那里的参天大树。","explanation_cn":"过去完成进行时,表示到过去某时为止已持续生长了几个世纪。✓ the great trees which had been growing there for centuries. ✗ grew:一般过去;✗ have been growing:现在完成进行;✗ were growing:过去进行。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp3','choice','{"stem":"\"I asked him what he ___.\"(宾语从句:主句过去,''丢了什么''用过去完成时)","options":["had lost","lost","was losing","has lost"],"answer_index":0,"stem_cn":"我问他丢了什么。","explanation_cn":"问话在过去(I asked),\"丢了什么\"发生在问之前,用过去完成时。✓ I asked him what he had lost. ✗ lost:一般过去,分不出先后;✗ has lost:现在完成,与 asked 的过去冲突;✗ was losing:过去进行。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp3','choice','{"stem":"\"I asked him what he ___ all afternoon.\"(宾语从句:''整个下午一直在做什么''用过去完成进行时)","options":["was doing","had been doing","has been doing","did"],"answer_index":1,"stem_cn":"我问他整个下午在干什么。","explanation_cn":"问话在过去,\"整个下午一直在做什么\"强调之前一直持续的过程,用过去完成进行时。✓ I asked him what he had been doing all afternoon. ✗ did:一般过去;✗ has been doing:现在完成进行;✗ was doing:过去进行,不含\"整个下午一直\"。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp4','choice','{"stem":"\"The inspector ___ my ticket.\"(易混词:检票员''查验''我的票)","options":["sprayed","controlled","ordered","checked"],"answer_index":3,"stem_cn":"检票员查验了我的票。","explanation_cn":"\"查验、检查\"车票用 check。✓ The inspector checked my ticket. ✗ controlled:意为\"控制、掌管\",不表\"查验\";✗ ordered:命令/订购;✗ sprayed:喷撒。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp4','choice','{"stem":"\"He ___ a large business company.\"(易混词:''掌管、控制''一家公司)","options":["sprays","controls","floods","checks"],"answer_index":1,"stem_cn":"他掌管着一家很大的商业公司。","explanation_cn":"\"掌管、控制\"一家公司用 control。✓ He controls a large business company. ✗ checks:意为\"检查\",不表\"掌管\";✗ sprays:喷撒;✗ floods:淹没。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp4','choice','{"stem":"\"Have you ___ those figures?\"(易混词:''核对''那些数字)","options":["controlled","blackened","planted","checked"],"answer_index":3,"stem_cn":"你核对过那些数字了吗?","explanation_cn":"\"核对\"数字用 check。✓ Have you checked those figures? ✗ controlled:控制;✗ planted:种植;✗ blackened:使变黑。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp5','choice','{"stem":"\"Beethoven was a ___ composer.\"(易混词:''伟大的''作曲家)","options":["big","great","tall","wide"],"answer_index":1,"stem_cn":"贝多芬是一位伟大的作曲家。","explanation_cn":"\"伟大的\"作曲家用 great(强调重要、卓越)。✓ Beethoven was a great composer. ✗ big:指体积大;✗ tall:高;✗ wide:宽。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp5','choice','{"stem":"\"Skyscrapers are ___ buildings.\"(易混词:''高大的''楼房,指体积)","options":["big","famous","important","great"],"answer_index":0,"stem_cn":"摩天大楼是高大的楼房。","explanation_cn":"形容楼房体积\"高大的\"用 big。✓ Skyscrapers are big buildings. ✗ great:强调重要、伟大,不指体积;✗ important:重要;✗ famous:著名。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp5','choice','{"stem":"\"The Parthenon is a ___ building — an important one.\"(易混词:''重要/伟大的''建筑)","options":["high","long","big","great"],"answer_index":3,"stem_cn":"巴台农神殿是一座重要的建筑。","explanation_cn":"\"重要的、了不起的\"建筑用 great。✓ The Parthenon is a great building. ✗ big:仅指体积;✗ high:高;✗ long:长。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp6','choice','{"stem":"\"Olive trees can grow in poor ___.\"(易混词:''土壤''——供植物生长的养分层)","options":["land","floor","soil","ground"],"answer_index":2,"stem_cn":"橄榄树能在贫瘠的土壤里生长。","explanation_cn":"供植物生长的\"土壤\"用 soil。✓ Olive trees can grow in poor soil. ✗ ground:指地面,不指养分层;✗ floor:室内地板;✗ land:陆地、土地(面积)。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp6','choice','{"stem":"\"The ball fell to the ___.\"(易混词:''地面'')","options":["sky","soil","wall","ground"],"answer_index":3,"stem_cn":"球落到地面上。","explanation_cn":"\"地面\"用 ground。✓ The ball fell to the ground. ✗ soil:土壤;✗ sky:天空;✗ wall:墙。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',5,'am2_l62_gp6','choice','{"stem":"\"Nothing can grow in this poor ___.\"(易混词:''土壤'')","options":["soil","stone","air","ground"],"answer_index":0,"stem_cn":"这贫瘠的土壤里什么也长不出来。","explanation_cn":"供植物生长的\"土壤\"用 soil。✓ Nothing can grow in this poor soil. ✗ ground:地面;✗ stone:石头;✗ air:空气。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',6,NULL,'choice','{"stem":"美语里\"消防员\"常说:","options":["firefighter","fire worker","fire soldier","fireman"],"answer_index":0,"explanation_cn":"美语\"消防员\"常说 firefighter(不分性别);英式旧说 fireman。✓ Firefighters had been fighting the fire. 消防员一直在扑救大火。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',6,NULL,'choice','{"stem":"美语里\"飞机\"常说:","options":["aeroplane","flying machine","air boat","airplane"],"answer_index":3,"explanation_cn":"美语\"飞机\"常说 airplane(或 plane);英式说 aeroplane。✓ The seed was sprayed by airplanes. 草籽由飞机撒播。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',6,NULL,'choice','{"stem":"desolate 的意思是:","options":["潮湿的","繁华的","荒凉的","陡峭的"],"answer_index":2,"explanation_cn":"desolate = 荒凉的。✓ over the desolate hills 在荒凉的山丘上。\n顺带记:繁华的 = busy;潮湿的 = wet;陡峭的 = steep."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',6,NULL,'choice','{"stem":"threaten 的意思是:","options":["威胁","邀请","感谢","保护"],"answer_index":0,"explanation_cn":"threaten = 威胁。✓ threatened the villages with destruction 对村庄构成毁灭性威胁。\n顺带记:保护 = protect;感谢 = thank;邀请 = invite."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',6,NULL,'choice','{"stem":"flood 的意思是:","options":["大火","洪水,水灾","地震","干旱"],"answer_index":1,"explanation_cn":"flood = 洪水、水灾。✓ would cause serious floods 会引起严重的水灾。\n顺带记:干旱 = drought;大火 = fire;地震 = earthquake."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',6,NULL,'choice','{"stem":"century 的意思是:","options":["世纪","星期","季节","年代"],"answer_index":0,"explanation_cn":"century = 世纪。✓ growing there for centuries 在那里生长了几个世纪。\n顺带记:年代 = decade;星期 = week;季节 = season."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',7,NULL,'cloze','{"stem":"第 1 空","context":"Firefighters ___1___ the forest fire for nearly three weeks before they could get it under control. When the fire ___2___ at last put out, the authorities ordered grass-seed. The planes ___3___ seed for nearly a month when it began to rain. By then, in many places the grass ___4___ root.","blank_no":1,"options":["had been fighting","fought","have been fighting","were fighting"],"answer_index":0,"explanation_cn":"过去完成进行时,强调到过去某时为止已持续三周。✓ Firefighters had been fighting the forest fire for nearly three weeks.\n✗ fought:一般过去;✗ have been fighting:现在完成进行;✗ were fighting:过去进行。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',7,NULL,'cloze','{"stem":"第 2 空","context":"Firefighters ___1___ the forest fire for nearly three weeks before they could get it under control. When the fire ___2___ at last put out, the authorities ordered grass-seed. The planes ___3___ seed for nearly a month when it began to rain. By then, in many places the grass ___4___ root.","blank_no":2,"options":["had been","was","has been","is being"],"answer_index":0,"explanation_cn":"\"When the fire had at last been put out\"用过去完成时的被动 had been + 过去分词。✓ When the fire had been put out, the authorities ordered grass-seed.\n✗ was:一般过去,分不出先后;✗ has been:现在完成;✗ is being:现在进行被动。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',7,NULL,'cloze','{"stem":"第 3 空","context":"Firefighters ___1___ the forest fire for nearly three weeks before they could get it under control. When the fire ___2___ at last put out, the authorities ordered grass-seed. The planes ___3___ seed for nearly a month when it began to rain. By then, in many places the grass ___4___ root.","blank_no":3,"options":["had been planting","planted","have been planting","were planting"],"answer_index":0,"explanation_cn":"过去完成进行时,到\"开始下雨\"为止已持续近一个月。✓ The planes had been planting seed for nearly a month.\n✗ planted:一般过去;✗ have been planting:现在完成进行;✗ were planting:过去进行。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',7,NULL,'cloze','{"stem":"第 4 空","context":"Firefighters ___1___ the forest fire for nearly three weeks before they could get it under control. When the fire ___2___ at last put out, the authorities ordered grass-seed. The planes ___3___ seed for nearly a month when it began to rain. By then, in many places the grass ___4___ root.","blank_no":4,"options":["had already taken","took","has taken","was taking"],"answer_index":0,"explanation_cn":"过去完成时,到那时草已经生根。✓ By then, the grass had already taken root.\n✗ took:一般过去;✗ has taken:现在完成;✗ was taking:过去进行。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',8,NULL,'choice','{"stem":"How long had the firemen been fighting the fire before they got it under control?","options":["For nearly three weeks","For a few days","For a month","For a whole year"],"answer_index":0,"explanation_cn":"课文说 Firemen had been fighting the forest fire for nearly three weeks before they could get it under control。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',8,NULL,'choice','{"stem":"Why did the forest authorities order grass-seed?","options":["To sell it for money","So the grass would hold the soil and prevent floods after heavy rain","To feed the animals","To make the hills look green for tourists"],"answer_index":1,"explanation_cn":"课文说大雨会冲走土壤、引起水灾,当局订购迅速生长的草籽来固土防灾。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',8,NULL,'choice','{"stem":"What had begun to appear in the blackened soil by the end?","options":["New great trees","Snow","More smoke","Patches of green grass"],"answer_index":3,"explanation_cn":"课文说 patches of green had begun to appear in the blackened soil。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',9,NULL,'choice','{"stem":"你想说\"我到达之前他已经完成了工作\"(过去完成时:过去的过去):","options":["He had already finished work before I arrived.","He has already finished work before I arrived.","He was already finishing work before I arrived.","He already finished work before I had arrived."],"answer_index":0,"explanation_cn":"过去完成时 had + 过去分词,表示在过去某时(我到达)之前已经完成。✓ He had already finished work before I arrived. 场合:说过去两件事的先后。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',9,NULL,'choice','{"stem":"你想说\"在得到这份工作前,他已经在一家工厂干了多年\"(过去完成进行时:强调持续):","options":["He had been work in a factory for years before he got this job.","He is working in a factory for years before he got this job.","He has been working in a factory for years before he got this job.","He had been working in a factory for years before he got this job."],"answer_index":3,"explanation_cn":"过去完成进行时 had been + 现在分词,强调到过去某时为止一直持续的过程。✓ He had been working in a factory for years before he got this job. 场合:说过去某时之前已持续做某事多年。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',9,NULL,'choice','{"stem":"你想说\"检票员查验了我的票\"(用 check 表''查验''):","options":["The inspector rooted my ticket.","The inspector checked my ticket.","The inspector controlled my ticket.","The inspector sprayed my ticket."],"answer_index":1,"explanation_cn":"\"查验、检查\"车票用 check。✓ The inspector checked my ticket. 场合:检票、核对时用 check,不用 control。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"flood 的意思是:","options":["洪水,水灾","地震","干旱","大火"],"answer_index":0,"explanation_cn":"flood = 洪水、水灾。✓ would cause serious floods 会引起严重的水灾。\n顺带记:干旱 = drought;大火 = fire;地震 = earthquake."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"century 的意思是:","options":["年代","季节","星期","世纪"],"answer_index":3,"explanation_cn":"century = 世纪。✓ growing there for centuries 生长了几个世纪。\n顺带记:年代 = decade;星期 = week;季节 = season."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"\"Firefighters ___ the fire for nearly three weeks before they got it under control.\"(过去完成进行时)","options":["fought","have been fighting","had been fighting","were fighting"],"answer_index":2,"stem_cn":"消防员同大火搏斗了将近3个星期才控制住。","explanation_cn":"过去完成进行时,强调持续三周直到过去某时。✓ Firefighters had been fighting the fire for nearly three weeks.\n✗ fought:一般过去;✗ have been fighting:现在完成进行;✗ were fighting:过去进行。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"\"By then, in many places the grass ___ already taken root.\"(过去完成时)","options":["was","would","has","had"],"answer_index":3,"stem_cn":"到那时,很多地方的草已经生了根。","explanation_cn":"过去完成时,到那时草已经生根。✓ By then, the grass had already taken root.\n✗ has:现在完成;✗ was:构不成完成;✗ would:表将来。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"\"had been + 现在分词\"这种形式表示的时间概念是:","options":["过去某时之前一直在进行","将来会进行","现在正在进行","一次性的过去动作"],"answer_index":0,"explanation_cn":"had been + 现在分词是过去完成进行时,表示到过去某个时间点为止动作一直在持续进行。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"\"take root\" 的意思是:","options":["枯萎","生根","开花","拔掉"],"answer_index":1,"explanation_cn":"take root = 生根、扎根。✓ The grass had taken root. 草已经生了根。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"Why did the hills threaten the surrounding villages after the fire?","options":["The fire was still burning there","Smoke covered the villages","Heavy rain would wash away the soil and cause serious floods","The trees fell on them"],"answer_index":2,"passage":"Firefighters had been fighting the forest fire for nearly three weeks before they could get it under control. A short time before, great trees had covered the countryside for miles around. Now, smoke still rose up from the warm ground over the desolate hills. Winter was coming on and the hills threatened the surrounding villages with destruction, for heavy rain would not only wash away the soil but would cause serious floods as well. When the fire had at last been put out, the forest authorities ordered several tons of a special type of grass-seed which would grow quickly. The seed was sprayed over the ground in huge quantities by airplanes. The planes had been planting seed for nearly a month when it began to rain. By then, however, in many places the grass had already taken root. In place of the great trees which had been growing there for centuries, patches of green had begun to appear in the blackened soil.","explanation_cn":"课文说 heavy rain would not only wash away the soil but would cause serious floods as well。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"How was the grass-seed spread over the ground?","options":["It was blown there by the wind","It was sprayed in huge quantities by airplanes","It was planted by hand by the firemen","It was dropped by trucks"],"answer_index":1,"passage":"Firefighters had been fighting the forest fire for nearly three weeks before they could get it under control. A short time before, great trees had covered the countryside for miles around. Now, smoke still rose up from the warm ground over the desolate hills. Winter was coming on and the hills threatened the surrounding villages with destruction, for heavy rain would not only wash away the soil but would cause serious floods as well. When the fire had at last been put out, the forest authorities ordered several tons of a special type of grass-seed which would grow quickly. The seed was sprayed over the ground in huge quantities by airplanes. The planes had been planting seed for nearly a month when it began to rain. By then, however, in many places the grass had already taken root. In place of the great trees which had been growing there for centuries, patches of green had begun to appear in the blackened soil.","explanation_cn":"课文说 The seed was sprayed over the ground in huge quantities by airplanes。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"What was the danger to the villages after the fire?","options":["Falling trees","Wild animals","Heavy rain could cause serious floods","Another fire"],"answer_index":2,"audio":"Firefighters had been fighting the forest fire for nearly three weeks before they could get it under control. A short time before, great trees had covered the countryside for miles around. Now, smoke still rose up from the warm ground over the desolate hills. Winter was coming on and the hills threatened the surrounding villages with destruction, for heavy rain would not only wash away the soil but would cause serious floods as well. When the fire had at last been put out, the forest authorities ordered several tons of a special type of grass-seed which would grow quickly. The seed was sprayed over the ground in huge quantities by airplanes. The planes had been planting seed for nearly a month when it began to rain. By then, however, in many places the grass had already taken root. In place of the great trees which had been growing there for centuries, patches of green had begun to appear in the blackened soil.","explanation_cn":"课文说冬季将至,大雨会冲走土壤并引起严重水灾,威胁周围村庄。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l62',10,NULL,'choice','{"stem":"What began to grow after the planes planted the seed?","options":["New tall trees","Patches of green grass in the blackened soil","Nothing at all","More smoke"],"answer_index":1,"audio":"Firefighters had been fighting the forest fire for nearly three weeks before they could get it under control. A short time before, great trees had covered the countryside for miles around. Now, smoke still rose up from the warm ground over the desolate hills. Winter was coming on and the hills threatened the surrounding villages with destruction, for heavy rain would not only wash away the soil but would cause serious floods as well. When the fire had at last been put out, the forest authorities ordered several tons of a special type of grass-seed which would grow quickly. The seed was sprayed over the ground in huge quantities by airplanes. The planes had been planting seed for nearly a month when it began to rain. By then, however, in many places the grass had already taken root. In place of the great trees which had been growing there for centuries, patches of green had begun to appear in the blackened soil.","explanation_cn":"课文说 patches of green had begun to appear in the blackened soil。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
